1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  cursed?: boolean;
8	  enchantment?: number;
9	}
10	
11	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
12	  sword: 100,
13	  amulet: 60,
14	  staff: 80,
15	  potion: 40,
16	};
17	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
18	const COMPONENT_BASE_PREMIUM = 25;
19	const BLOCK_SIZE = 3;
20	const BLOCK_BASE_PREMIUM = 60;
21	const CURSE_SURCHARGE_RATE = 0.5;
22	const HIGH_ENCHANTMENT_LEVEL = 5;
23	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
24	const LOYALTY_YEARS = 2;
25	const LOYALTY_DISCOUNT_RATE = 0.2;
26	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
27	const PROCESSING_FEE = 5;
28	
29	function isComponent(item: Item): boolean {
30	  return COMPONENT_TYPES.has(item.type);
31	}
32	
33	function isMainItem(item: Item): boolean {
34	  return !isComponent(item);
35	}
36	
37	function mainItemBasePremium(item: Item): number {
38	  return MAIN_ITEM_BASE_PREMIUMS[item.type];
39	}
40	
41	function alikeGroupBasePremium(count: number): number {
42	  return count === BLOCK_SIZE
43	    ? BLOCK_BASE_PREMIUM
44	    : count * COMPONENT_BASE_PREMIUM;
45	}
46	
47	/** Components are "alike" when they are of exactly the same type. */
48	function alikeKey(component: Item): string {
49	  return component.type;
50	}
51	
52	function componentsBasePremium(components: Item[]): number {
53	  const countsPerAlikeGroup = new Map<string, number>();
54	  for (const component of components) {
55	    const key = alikeKey(component);
56	    countsPerAlikeGroup.set(key, (countsPerAlikeGroup.get(key) ?? 0) + 1);
57	  }
58	  return [...countsPerAlikeGroup.values()].reduce(
59	    (total, count) => total + alikeGroupBasePremium(count),
60	    0,
61	  );
62	}
63	
64	function curseSurcharge(item: Item): number {
65	  return item.cursed === true
66	    ? mainItemBasePremium(item) * CURSE_SURCHARGE_RATE
67	    : 0;
68	}
69	
70	function isHighlyEnchanted(item: Item): boolean {
71	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
72	}
73	
74	function highEnchantmentSurcharge(item: Item): number {
75	  return isHighlyEnchanted(item)
76	    ? mainItemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
77	    : 0;
78	}
79	
80	/**
81	 * Item-specific modifiers apply to the base premium of the affected item and
82	 * are added to it, never multiplied onto it. Each risk rule is independent:
83	 * its own condition, its own rate.
84	 */
85	function itemSpecificModifiers(item: Item): number {
86	  return curseSurcharge(item) + highEnchantmentSurcharge(item);
87	}
88	
89	function mainItemsBasePremium(mainItems: Item[]): number {
90	  return mainItems.reduce((total, item) => total + mainItemBasePremium(item), 0);
91	}
92	
93	/** The policy base premium: the sum of all unmodified item base premiums. */
94	function policyBasePremiumFor(items: Item[]): number {
95	  return (
96	    mainItemsBasePremium(items.filter(isMainItem)) +
97	    componentsBasePremium(items.filter(isComponent))
98	  );
99	}
100	
101	/** The item-specific surcharges of every affected item, summed. */
102	function itemSpecificModifiersFor(items: Item[]): number {
103	  return items
104	    .filter(isMainItem)
105	    .reduce((total, item) => total + itemSpecificModifiers(item), 0);
106	}
107	
108	function roundInMHPCOsFavour(premium: number): number {
109	  return Math.ceil(premium);
110	}
111	
112	/** Every item in a quote is treated as a first insurance. */
113	function firstInsuranceSurcharge(policyBasePremium: number): number {
114	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
115	}
116	
117	/**
118	 * Policy-wide modifiers apply to the policy base premium (the sum of all item
119	 * base premiums) and are added to it, never multiplied onto it. Each rule is
120	 * independent: its own condition, its own rate.
121	 */
122	function isLongStanding(customer: Customer): boolean {
123	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
124	}
125	
126	function loyaltyDiscount(customer: Customer, policyBasePremium: number): number {
127	  return isLongStanding(customer)
128	    ? -policyBasePremium * LOYALTY_DISCOUNT_RATE
129	    : 0;
130	}
131	
132	function policyWideModifiers(
133	  customer: Customer,
134	  policyBasePremium: number,
135	): number {
136	  return (
137	    firstInsuranceSurcharge(policyBasePremium) +
138	    loyaltyDiscount(customer, policyBasePremium)
139	  );
140	}
141	
142	export function quote(customer: Customer, items: Item[]): number {
143	  const policyBasePremium = policyBasePremiumFor(items);
144	  const premium =
145	    policyBasePremium +
146	    itemSpecificModifiersFor(items) +
147	    policyWideModifiers(customer, policyBasePremium) +
148	    PROCESSING_FEE;
149	  return roundInMHPCOsFavour(premium);
150	}
